    Installed     = false,
    TickerRunning = false,
    RotateRunning = false,
    RetryTimer    = false,
    OrigHooks     = {},
    FrameIDs      = 2002901,
    AvatarIDs     = 30397,
    Config = {
        SELF_BG_ID    = 61510019,
        SELF_CARTE_ID = 61100092,
        GOLD_PLAN_ID  = 61910001,
        SWAP_LIST = {
            [61510000] = 61510019,
            [61100001] = 61100092,
            [61300001] = 61300066,
        },

        -- Frame behavior
        FrameMode      = "random",  -- "off" | "fixed" | "random" | "cycle"
        FrameIndex     = 1,         -- used when FrameMode == "fixed" or "cycle"
        FrameRotateSec = 5,         -- rotate interval (seconds)
        CurrentFrameID = 2002901,   -- live applied value (auto-managed)
        

        -- Avatar behavior
        AvatarMode      = "off",    -- "off" | "fixed" | "random" | "cycle"
        AvatarIndex     = 1,
        AvatarRotateSec = 5,
        CurrentAvatarID = 30397,        -- 0 = don't touch head icon
    },
}

local FAV  = _G.FrameAvatarFake
local FAVC = FAV.Config

local function FAV_On()
    return (_G.LexusConfig and _G.LexusConfig.FakeFrameAvatar) == true
end

local function FAV_IsSelfUid(uid)
    local l = DataMgr and DataMgr.roleData and tonumber(DataMgr.roleData.uid)
    return l and tostring(uid) == tostring(l)
end

local function FAV_Require(p)
    local ok, m = pcall(require, p)
    return ok and m or nil
end

local function FAV_GetTicker()
    if _G.Mytimer_ticker then return _G.Mytimer_ticker end
    if _G.timer_ticker   then return _G.timer_ticker   end
    local ok, t = pcall(require, "common.time_ticker")
    if ok and t and t.AddTimerLoop then
        _G.timer_ticker = t
        return t
    end
    return nil
end

-- ══════════════════════════════════════════════════════════════════════
-- ID PICKERS — read from FAV.FrameIDs / FAV.AvatarIDs
-- ══════════════════════════════════════════════════════════════════════

local function FAV_PickFrameID()
    local list = FAV.FrameIDs
    if not list or #list == 0 then return 0 end
    local mode = FAVC.FrameMode or "off"
    if mode == "off" then return 0 end

    if mode == "fixed" then
        local idx = math.max(1, math.min(#list, tonumber(FAVC.FrameIndex) or 1))
        return list[idx]
    end
    if mode == "random" then
        return list[math.random(1, #list)]
    end
    -- cycle
    FAVC.FrameIndex = ((tonumber(FAVC.FrameIndex) or 0) % #list) + 1
    return list[FAVC.FrameIndex]
end

local function FAV_PickAvatarID()
    local list = FAV.AvatarIDs
    if not list or #list == 0 then return 0 end
    local mode = FAVC.AvatarMode or "off"
    if mode == "off" then return 0 end

    if mode == "fixed" then
        local idx = math.max(1, math.min(#list, tonumber(FAVC.AvatarIndex) or 1))
        return list[idx]
    end
    if mode == "random" then
        return list[math.random(1, #list)]
    end
    FAVC.AvatarIndex = ((tonumber(FAVC.AvatarIndex) or 0) % #list) + 1
    return list[FAVC.AvatarIndex]
end

-- ══════════════════════════════════════════════════════════════════════
-- LAYER 1 — CDataTable id swap (specific overrides)
-- ══════════════════════════════════════════════════════════════════════
local function FAV_HookDataTable()
    if FAV.OrigHooks.dtSwap then return true end
    if type(CDataTable) ~= "table" or type(CDataTable.GetTableData) ~= "function" then
        return false
    end
    local orig = CDataTable.GetTableData
    FAV.OrigHooks.dtSwap = orig
    CDataTable.GetTableData = function(tblName, id, ...)
        if FAV_On() then
            local swapTo = FAVC.SWAP_LIST[tonumber(id)]
            if swapTo then
                local ok, cfg = pcall(orig, tblName, swapTo, ...)
                if ok and cfg then return cfg end
            end
        end
        return orig(tblName, id, ...)
    end
    return true
end

-- ══════════════════════════════════════════════════════════════════════
-- LAYER 2 — Role info background
-- ══════════════════════════════════════════════════════════════════════
local function FAV_HookBG()
    if FAV.OrigHooks.bgSelf and FAV.OrigHooks.bgPlayer then return true end
    if not (ModuleManager and ModuleManager.GetModule and ModuleManager.LobbyModuleConfig) then
        return false
    end
    local ok, m = pcall(ModuleManager.GetModule, ModuleManager.LobbyModuleConfig.logic_roleInfo_background)
    if not ok or type(m) ~= "table" then return false end

    if not FAV.OrigHooks.bgSelf and type(m.GetSelfRoleInfoBGID) == "function" then
        local orig = m.GetSelfRoleInfoBGID
        FAV.OrigHooks.bgSelf = orig
        m.GetSelfRoleInfoBGID = function(self, ...)
            if FAV_On() then return FAVC.SELF_BG_ID end
            return orig(self, ...)
        end
    end
    if not FAV.OrigHooks.bgPlayer and type(m.GetPlayerRoleInfoBGID) == "function" then
        local orig = m.GetPlayerRoleInfoBGID
        FAV.OrigHooks.bgPlayer = orig
        m.GetPlayerRoleInfoBGID = function(self, uid, ...)
            if FAV_On() and FAV_IsSelfUid(uid) then return FAVC.SELF_BG_ID end
            return orig(self, uid, ...)
        end
    end
    return FAV.OrigHooks.bgSelf ~= nil and FAV.OrigHooks.bgPlayer ~= nil
end

-- ══════════════════════════════════════════════════════════════════════
-- LAYER 3 — Carte frame
-- ══════════════════════════════════════════════════════════════════════
local function FAV_HookCarte()
    if FAV.OrigHooks.carte then return true end
    local sc = FAV_Require("client.slua.logic.lobby.Left.logic_social_card")
    if type(sc) ~= "table" or type(sc.GetCarteFrameEquipIdByProfile) ~= "function" then
        return false
    end
    local orig = sc.GetCarteFrameEquipIdByProfile
    FAV.OrigHooks.carte = orig
    sc.GetCarteFrameEquipIdByProfile = function(profile, ...)
        if FAV_On() and profile and type(profile) == "table" and FAV_IsSelfUid(profile.uid) then
            return FAVC.SELF_CARTE_ID
        end
        return orig(profile, ...)
    end
    return true
end

-- ══════════════════════════════════════════════════════════════════════
-- LAYER 4 — Nickname color (gold)
-- ══════════════════════════════════════════════════════════════════════
local function FAV_HookNick()
    if FAV.OrigHooks.nick then return true end
    if not (ModuleManager and ModuleManager.GetModule and ModuleManager.CommonModuleConfig) then
        return false
    end
    local ok, mgr = pcall(ModuleManager.GetModule, ModuleManager.CommonModuleConfig.NicknameColorManager)
    if not ok or type(mgr) ~= "table" or type(mgr.GetUserData) ~= "function" then
        return false
    end
    local orig = mgr.GetUserData
    FAV.OrigHooks.nick = orig
    mgr.GetUserData = function(self, UID)
        if FAV_On() and FAV_IsSelfUid(UID) then
            return FAVC.GOLD_PLAN_ID
        end
        return orig(self, UID)
    end
    return true
end

-- ══════════════════════════════════════════════════════════════════════
-- LAYER 5 — Apply currently-selected frame/avatar (SAFE — no RPC)
-- ══════════════════════════════════════════════════════════════════════
local function FAV_ApplyAvatar()
    if not FAV_On() then return end
    if not (DataMgr and DataMgr.roleData) then return end
    local rd = DataMgr.roleData
    local changed = false

    local frameID = tonumber(FAVC.CurrentFrameID) or 0
    if frameID > 0 then
        local cur = tonumber(rd.cur_avatar_box_id) or 0
        if cur ~= frameID then
            -- SAFE: direct field set, no DataMgr.Update* (no server RPC)
            pcall(function() rd.cur_avatar_box_id = frameID end)
            changed = true
        end
        pcall(function()
            local af = require("client.slua.logic.roleInfo.logic_RoleInfoAvatarFrame")
            if af then
                af.AvatarFrameList = af.AvatarFrameList or {}
                af.AvatarFrameList[frameID] = af.AvatarFrameList[frameID] or { expire_time = 1 }
                af.AvatarFrameList[frameID].expire_time = 1
                af.HasGet = true
                af._hasGotData = true
            end
        end)
    end

    local avatarID = tonumber(FAVC.CurrentAvatarID) or 0
    if avatarID > 0 then
        local want = tostring(avatarID)
        if tostring(rd.headIconUrl) ~= want then
            pcall(function() rd.headIconUrl = want end)
            changed = true
            pcall(function()
                local big = require("client.slua.logic.roleInfo.logic_roleInfo_BigAvatar")
                if big and big.RefreshBigImage then big.RefreshBigImage(want) end
            end)
        end
        pcall(function()
            local av = require("client.slua.logic.roleInfo.logic_roleInfo_Avatar")
            if av then
                av.HeadportraitList = av.HeadportraitList or {}
                if av.HeadportraitList[want] == nil then
                    av.HeadportraitList[want] = 1
                end
            end
        end)
    end

    if changed then
        pcall(function()
            EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO)
            EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_HEAD_INFO, rd.headIconUrl)
            EventSystem:postEvent(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_USE_AVATAR)
            EventSystem:postEvent(EVENTTYPE_LOBBY, EVENTID_UPDATE_LOBBY_AVATAR)
            EventSystem:postEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_LOBBY_SOCIAL_UPDATE_HEAD_ICON)
        end)
    end
end

-- ══════════════════════════════════════════════════════════════════════
-- ROTATOR — refill CurrentFrameID / CurrentAvatarID from lists
-- ══════════════════════════════════════════════════════════════════════
local function FAV_StartRotator()
    if FAV.RotateRunning then return end
    local tk = FAV_GetTicker()
    if not (tk and tk.AddTimerLoop) then return end
    FAV.RotateRunning = true

    -- Frame rotation
    tk.AddTimerLoop(0, function()
        if not FAV_On() then return end
        local id = FAV_PickFrameID()
        if id and id ~= FAVC.CurrentFrameID then
            FAVC.CurrentFrameID = id
        end
    end, -1, tonumber(FAVC.FrameRotateSec) or 5)

    -- Avatar rotation
    tk.AddTimerLoop(0, function()
        if not FAV_On() then return end
        local id = FAV_PickAvatarID()
        if id and id ~= FAVC.CurrentAvatarID then
            FAVC.CurrentAvatarID = id
        end
    end, -1, tonumber(FAVC.AvatarRotateSec) or 5)
end

-- ══════════════════════════════════════════════════════════════════════
-- INSTALL / UNINSTALL
-- ══════════════════════════════════════════════════════════════════════
function FAV_Install()
    if FAV.Installed then return true end

    local done = true
    if not FAV_HookDataTable() then done = false end
    if not FAV_HookBG()        then done = false end
    if not FAV_HookCarte()     then done = false end
    if not FAV_HookNick()      then done = false end

    if done then
        FAV.Installed = true
        pcall(FAV_ApplyAvatar)
    else
        if not FAV.RetryTimer then
            local tk = FAV_GetTicker()
            if tk and tk.AddTimerLoop then
                FAV.RetryTimer = true
                tk.AddTimerLoop(3, function()
                    if FAV.Installed then return end
                    if FAV_HookDataTable() and FAV_HookBG() and FAV_HookCarte() and FAV_HookNick() then
                        FAV.Installed = true
                        pcall(FAV_ApplyAvatar)
                    end
                end, 200, 1)
            end
        end
    end

    -- Kick the rotator so Current IDs update from lists
    pcall(FAV_StartRotator)

    -- Continuous apply loop (live toggle + rotate pickup)
    if not FAV.TickerRunning then
        local tk = FAV_GetTicker()
        if tk and tk.AddTimerLoop then
            FAV.TickerRunning = true
            tk.AddTimerLoop(0.5, function()
                if not FAV_On() then return end
                local okF, inFight = pcall(function()
                    return GameStatus and GameStatus.IsInFightingStatus and GameStatus.IsInFightingStatus()
                end)
                if okF and inFight then return end
                pcall(FAV_ApplyAvatar)
            end, -1, 1)
        end
    end
    return FAV.Installed
end

function FAV_Uninstall()
    pcall(function()
        if FAV.OrigHooks.dtSwap and CDataTable then
            CDataTable.GetTableData = FAV.OrigHooks.dtSwap
        end
    end)
    pcall(function()
        if ModuleManager and ModuleManager.LobbyModuleConfig then
            local ok, m = pcall(ModuleManager.GetModule, ModuleManager.LobbyModuleConfig.logic_roleInfo_background)
            if ok and m then
                if FAV.OrigHooks.bgSelf   then m.GetSelfRoleInfoBGID   = FAV.OrigHooks.bgSelf   end
                if FAV.OrigHooks.bgPlayer then m.GetPlayerRoleInfoBGID = FAV.OrigHooks.bgPlayer end
            end
        end
    end)
    pcall(function()
        local sc = FAV_Require("client.slua.logic.lobby.Left.logic_social_card")
        if sc and FAV.OrigHooks.carte then
            sc.GetCarteFrameEquipIdByProfile = FAV.OrigHooks.carte
        end
    end)
    pcall(function()
        if ModuleManager and ModuleManager.CommonModuleConfig then
            local ok, mgr = pcall(ModuleManager.GetModule, ModuleManager.CommonModuleConfig.NicknameColorManager)
            if ok and mgr and FAV.OrigHooks.nick then
                mgr.GetUserData = FAV.OrigHooks.nick
            end
        end
    end)
    FAV.OrigHooks = {}
    FAV.Installed = false
    return true
end

function FAV_SetEnabled(on)
    if on then FAV_Install() else FAV_Uninstall() end
end

-- Public API — manual control if needed
function FAV_SetFrameMode(mode)    FAVC.FrameMode    = mode or "off" end
function FAV_SetAvatarMode(mode)   FAVC.AvatarMode   = mode or "off" end
function FAV_SetFrameIndex(idx)    FAVC.FrameIndex   = tonumber(idx) or 1 end
function FAV_SetAvatarIndex(idx)   FAVC.AvatarIndex  = tonumber(idx) or 1 end
function FAV_SetFrameRotate(sec)   FAVC.FrameRotateSec  = tonumber(sec) or 5 end
function FAV_SetAvatarRotate(sec)  FAVC.AvatarRotateSec = tonumber(sec) or 5 end
function FAV_ForceNextFrame()      FAVC.CurrentFrameID  = FAV_PickFrameID()  end
function FAV_ForceNextAvatar()     FAVC.CurrentAvatarID = FAV_PickAvatarID() end

_G.FAV             = FAV
_G.FrameAvatarFake = FAV
_G.FAV_Install     = FAV_Install
_G.FAV_Uninstall   = FAV_Uninstall
_G.FAV_SetEnabled  = FAV_SetEnabled
_G.FAV_SetFrameMode    = FAV_SetFrameMode
_G.FAV_SetAvatarMode   = FAV_SetAvatarMode
_G.FAV_SetFrameIndex   = FAV_SetFrameIndex
_G.FAV_SetAvatarIndex  = FAV_SetAvatarIndex
_G.FAV_SetFrameRotate  = FAV_SetFrameRotate
_G.FAV_SetAvatarRotate = FAV_SetAvatarRotate
_G.FAV_ForceNextFrame  = FAV_ForceNextFrame
_G.FAV_ForceNextAvatar = FAV_ForceNextAvatar

pcall(FAV_Install)

