-----===============SOCIAL LOBBY UNLOCK------
pcall(function()
    local Logic_SocialLobbyModule = ModuleManager and ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.Logic_SocialLobbyModule)
    if not Logic_SocialLobbyModule then return end

    local function isSelfUid(uid)
        if not uid or not DataMgr or not DataMgr.roleData then return false end
        return tonumber(uid) == tonumber(DataMgr.roleData.uid)
    end

    local SLOT_AVATAR    = 1
    local SLOT_VEHICLE   = 2
    local SLOT_WEAPON    = 3
    local SLOT_PET       = 4
    local SLOT_BGWALL    = 100

    local WEAPON_SLOTS_MAX   = 8
    local VEHICLE_SLOTS_MAX  = 6
    local AVATAR_SLOTS_MAX   = 6
    local PET_SLOTS_MAX      = 4
    local ALL_SLOT_TYPES = { SLOT_AVATAR, SLOT_VEHICLE, SLOT_WEAPON, SLOT_PET }
    local MAX_SLOT_INDEX = 8

    -- Fake instids use a very high base so they can never collide with server instids
    local FAKE_INSTID_BASE = 1125899906842624 -- 2^50, safely inside Lua double's 2^53 int range

    local WEAPON_SLOTS = {
        [1] = 1101101007,
        [2] = 1101004246,
        [3] = 1101004218,
        [4] = 1101004226,
        [5] = 1101003227,
        [6] = 1101005098,
        [7] = 1101006085,
        [8] = 1101008146,
    }

    local VEHICLE_SLOTS = {
        [1] = 1961062,
        [2] = 1961152,
        [3] = 1961153,
        [4] = 0,
        [5] = 0,
        [6] = 0,
    }

    local AVATAR_SLOTS = {
        [1] = 1406469,
        [2] = 1406971,
        [3] = 1407895,
        [4] = 0,
        [5] = 0,
        [6] = 0,
    }

    local PET_SLOTS = {
        [1] = 50024,
        [2] = 0,
        [3] = 0,
        [4] = 0,
    }

    local function FakeInstId(nSlotType, nSlotIndex, nItemId)
        return FAKE_INSTID_BASE + nSlotType * 10000000 + nSlotIndex * 100000 + (nItemId % 100000)
    end

    -- ============================================================
    -- PURE WRITE — no recursion, no network
    -- ============================================================
    local function WriteAllSlotsTo(tSocialData)
        if not tSocialData then return end
        local nCurTime = os.time and os.time() or 9999999999

        if not tSocialData.mixed_hall_slot_unlock_info then
            tSocialData.mixed_hall_slot_unlock_info = {}
        end
        for _, st in ipairs(ALL_SLOT_TYPES) do
            if not tSocialData.mixed_hall_slot_unlock_info[st] then
                tSocialData.mixed_hall_slot_unlock_info[st] = {}
            end
        end
        for i = 1, WEAPON_SLOTS_MAX do tSocialData.mixed_hall_slot_unlock_info[SLOT_WEAPON][i] = nCurTime end
        for i = 1, VEHICLE_SLOTS_MAX do tSocialData.mixed_hall_slot_unlock_info[SLOT_VEHICLE][i] = nCurTime end
        for i = 1, AVATAR_SLOTS_MAX do tSocialData.mixed_hall_slot_unlock_info[SLOT_AVATAR][i] = nCurTime end
        for i = 1, PET_SLOTS_MAX do tSocialData.mixed_hall_slot_unlock_info[SLOT_PET][i] = nCurTime end

        if not tSocialData.mixed_data then tSocialData.mixed_data = {} end
        for _, st in ipairs(ALL_SLOT_TYPES) do
            if not tSocialData.mixed_data[st] then tSocialData.mixed_data[st] = {} end
        end

        for i = 1, WEAPON_SLOTS_MAX do
            local id = WEAPON_SLOTS[i]
            if id and id > 0 then
                tSocialData.mixed_data[SLOT_WEAPON][i] = {
                    resid = id,
                    instid = FakeInstId(SLOT_WEAPON, i, id),
                    weapon_id = 0
                }
            end
        end

        for i = 1, VEHICLE_SLOTS_MAX do
            local id = VEHICLE_SLOTS[i]
            if id and id > 0 then
                tSocialData.mixed_data[SLOT_VEHICLE][i] = {
                    resid = id,
                    instid = FakeInstId(SLOT_VEHICLE, i, id)
                }
            end
        end

        for i = 1, AVATAR_SLOTS_MAX do
            local id = AVATAR_SLOTS[i]
            if id and id > 0 then
                local existing = tSocialData.mixed_data[SLOT_AVATAR][i] or {
                    gender = 1, pose_type = 0, item_info = {}
                }
                if not existing.item_info then existing.item_info = {} end
                local nAvatarSlotType = 3
                pcall(function()
                    local cfg = CDataTable.GetTableData("Item", id)
                    if cfg then
                        local tools = require("client.slua.logic.lobby.Left.SocialLobby.Logic_AvatarWardrobeDataTools")
                        if tools and tools.GetAvatarSlotType then
                            nAvatarSlotType = tools.GetAvatarSlotType(cfg.ItemSubType) or 3
                        end
                    end
                end)
                existing.item_info[nAvatarSlotType] = {
                    resid = id,
                    instid = FakeInstId(SLOT_AVATAR, i, id),
                    origin_resid = 0
                }
                existing.bIsEditData = true
                tSocialData.mixed_data[SLOT_AVATAR][i] = existing
            end
        end

        for i = 1, PET_SLOTS_MAX do
            local id = PET_SLOTS[i]
            if id and id > 0 then
                tSocialData.mixed_data[SLOT_PET][i] = {
                    pet_id = id,
                    pet_dress = {}
                }
            end
        end
    end

    -- Keep a private original reference so ForceUnlockAllSlots doesn't recurse through our hook
    local orig_GetSocialData = Logic_SocialLobbyModule.GetSocialData

    function ForceUnlockAllSlots()
        local uid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
        if not uid then return end
        uid = tonumber(uid)
        local tSocialData = orig_GetSocialData(Logic_SocialLobbyModule, uid)
        if not tSocialData then return end
        WriteAllSlotsTo(tSocialData)
    end

    local function FireSlotUpdateEvents(slotType, slotIndex)
        pcall(function()
            if EventSystem and EVENTTYPE_LOBBY_SOCIAL then
                if EVENTID_SOCIAL_LOBBY_SLOT_DATA_UPDATE then
                    EventSystem.postEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_SOCIAL_LOBBY_SLOT_DATA_UPDATE, slotType, slotIndex)
                end
                if EVENTID_GOT_SOCIAL_LOBBY_SHOW_DATA then
                    EventSystem.postEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_GOT_SOCIAL_LOBBY_SHOW_DATA)
                end
            end
        end)
    end

    local function FireShowDataEvent()
        pcall(function()
            if EventSystem and EVENTTYPE_LOBBY_SOCIAL and EVENTID_GOT_SOCIAL_LOBBY_SHOW_DATA then
                EventSystem.postEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_GOT_SOCIAL_LOBBY_SHOW_DATA)
            end
        end)
    end

    local function FireAllSlotEvents()
        for _, st in ipairs(ALL_SLOT_TYPES) do
            for i = 1, MAX_SLOT_INDEX do
                pcall(function()
                    if EventSystem and EVENTTYPE_LOBBY_SOCIAL and EVENTID_SOCIAL_LOBBY_SLOT_DATA_UPDATE then
                        EventSystem.postEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_SOCIAL_LOBBY_SLOT_DATA_UPDATE, st, i)
                    end
                end)
            end
        end
        FireShowDataEvent()
    end

    -- ============================================================
    -- Individual equip functions (kept for UI select hooks)
    -- ============================================================
    function EquipWeaponToSlot(nWeaponItemId, nSlotIndex)
        if not isSelfUid(DataMgr and DataMgr.roleData and DataMgr.roleData.uid) then return false end
        nSlotIndex = tonumber(nSlotIndex) or 1
        nWeaponItemId = tonumber(nWeaponItemId) or 0
        if nSlotIndex < 1 or nSlotIndex > WEAPON_SLOTS_MAX then return false end
        if nWeaponItemId <= 0 then return false end

        ForceUnlockAllSlots()
        local tSocialData = orig_GetSocialData(Logic_SocialLobbyModule, tonumber(DataMgr.roleData.uid))
        if not tSocialData then return false end
        if not tSocialData.mixed_data then tSocialData.mixed_data = {} end
        if not tSocialData.mixed_data[SLOT_WEAPON] then tSocialData.mixed_data[SLOT_WEAPON] = {} end

        tSocialData.mixed_data[SLOT_WEAPON][nSlotIndex] = {
            resid = nWeaponItemId,
            instid = FakeInstId(SLOT_WEAPON, nSlotIndex, nWeaponItemId),
            weapon_id = 0
        }
        WEAPON_SLOTS[nSlotIndex] = nWeaponItemId
        FireSlotUpdateEvents(SLOT_WEAPON, nSlotIndex)
        return true
    end

    function EquipVehicleToSlot(nVehicleItemId, nSlotIndex)
        nSlotIndex = tonumber(nSlotIndex) or 1
        nVehicleItemId = tonumber(nVehicleItemId) or 0
        if nSlotIndex < 1 or nSlotIndex > VEHICLE_SLOTS_MAX then return false end
        if nVehicleItemId <= 0 then return false end

        ForceUnlockAllSlots()
        local tSocialData = orig_GetSocialData(Logic_SocialLobbyModule, tonumber(DataMgr.roleData.uid))
        if not tSocialData then return false end
        if not tSocialData.mixed_data then tSocialData.mixed_data = {} end
        if not tSocialData.mixed_data[SLOT_VEHICLE] then tSocialData.mixed_data[SLOT_VEHICLE] = {} end

        tSocialData.mixed_data[SLOT_VEHICLE][nSlotIndex] = {
            resid = nVehicleItemId,
            instid = FakeInstId(SLOT_VEHICLE, nSlotIndex, nVehicleItemId)
        }
        VEHICLE_SLOTS[nSlotIndex] = nVehicleItemId
        FireSlotUpdateEvents(SLOT_VEHICLE, nSlotIndex)
        return true
    end

    function EquipAvatarToSlot(nItemId, nSlotIndex)
        nSlotIndex = tonumber(nSlotIndex) or 1
        nItemId = tonumber(nItemId) or 0
        if nSlotIndex < 1 or nSlotIndex > AVATAR_SLOTS_MAX then return false end
        if nItemId <= 0 then return false end

        ForceUnlockAllSlots()
        local tSocialData = orig_GetSocialData(Logic_SocialLobbyModule, tonumber(DataMgr.roleData.uid))
        if not tSocialData then return false end
        if not tSocialData.mixed_data then tSocialData.mixed_data = {} end
        if not tSocialData.mixed_data[SLOT_AVATAR] then tSocialData.mixed_data[SLOT_AVATAR] = {} end

        local nAvatarSlotType = 3
        pcall(function()
            local uItemCfg = CDataTable.GetTableData("Item", nItemId)
            if uItemCfg then
                local tools = require("client.slua.logic.lobby.Left.SocialLobby.Logic_AvatarWardrobeDataTools")
                if tools and tools.GetAvatarSlotType then
                    nAvatarSlotType = tools.GetAvatarSlotType(uItemCfg.ItemSubType) or 3
                end
            end
        end)

        local existing = tSocialData.mixed_data[SLOT_AVATAR][nSlotIndex] or {
            gender = 1, pose_type = 0, item_info = {}
        }
        if not existing.item_info then existing.item_info = {} end
        existing.item_info[nAvatarSlotType] = {
            resid = nItemId,
            instid = FakeInstId(SLOT_AVATAR, nSlotIndex, nItemId),
            origin_resid = 0
        }
        existing.bIsEditData = true
        tSocialData.mixed_data[SLOT_AVATAR][nSlotIndex] = existing
        AVATAR_SLOTS[nSlotIndex] = nItemId
        FireSlotUpdateEvents(SLOT_AVATAR, nSlotIndex)
        return true
    end

    function EquipPetToSlot(nPetId, nSlotIndex)
        nSlotIndex = tonumber(nSlotIndex) or 1
        nPetId = tonumber(nPetId) or 0
        if nSlotIndex < 1 or nSlotIndex > PET_SLOTS_MAX then return false end
        if nPetId <= 0 then return false end

        ForceUnlockAllSlots()
        local tSocialData = orig_GetSocialData(Logic_SocialLobbyModule, tonumber(DataMgr.roleData.uid))
        if not tSocialData then return false end
        if not tSocialData.mixed_data then tSocialData.mixed_data = {} end
        if not tSocialData.mixed_data[SLOT_PET] then tSocialData.mixed_data[SLOT_PET] = {} end

        tSocialData.mixed_data[SLOT_PET][nSlotIndex] = {
            pet_id = nPetId,
            pet_dress = {}
        }
        PET_SLOTS[nSlotIndex] = nPetId
        FireSlotUpdateEvents(SLOT_PET, nSlotIndex)
        return true
    end

    function UnequipSlot(nSlotType, nSlotIndex)
        nSlotType = tonumber(nSlotType) or 1
        nSlotIndex = tonumber(nSlotIndex) or 1
        local tSocialData = orig_GetSocialData(Logic_SocialLobbyModule, tonumber(DataMgr.roleData.uid))
        if not tSocialData or not tSocialData.mixed_data or not tSocialData.mixed_data[nSlotType] then return false end
        tSocialData.mixed_data[nSlotType][nSlotIndex] = nil
        FireSlotUpdateEvents(nSlotType, nSlotIndex)
        return true
    end

    function SwapSocialLobbyVehicleSlots(nSlotA, nSlotB)
        nSlotA = tonumber(nSlotA); nSlotB = tonumber(nSlotB)
        if not nSlotA or not nSlotB
            or nSlotA < 1 or nSlotA > VEHICLE_SLOTS_MAX
            or nSlotB < 1 or nSlotB > VEHICLE_SLOTS_MAX
            or nSlotA ~= math.floor(nSlotA) or nSlotB ~= math.floor(nSlotB) then
            return false, "invalid vehicle slot index"
        end
        if nSlotA == nSlotB then return true end
        local idA, idB = VEHICLE_SLOTS[nSlotA] or 0, VEHICLE_SLOTS[nSlotB] or 0
        VEHICLE_SLOTS[nSlotA], VEHICLE_SLOTS[nSlotB] = idB, idA
        local okA = idB <= 0 and UnequipSlot(SLOT_VEHICLE, nSlotA) or EquipVehicleToSlot(idB, nSlotA)
        local okB = idA <= 0 and UnequipSlot(SLOT_VEHICLE, nSlotB) or EquipVehicleToSlot(idA, nSlotB)
        if not okA or not okB then return false, "slot values swapped in memory, but local data refresh failed" end
        return true
    end

    function SetSocialLobbyVehicleSlotId(nSlotIndex, nVehicleItemId)
        nSlotIndex = tonumber(nSlotIndex); nVehicleItemId = tonumber(nVehicleItemId)
        if not nSlotIndex or nSlotIndex < 1 or nSlotIndex > VEHICLE_SLOTS_MAX or nSlotIndex ~= math.floor(nSlotIndex) then
            return false, "invalid vehicle slot index"
        end
        if not nVehicleItemId or nVehicleItemId <= 0 or nVehicleItemId ~= math.floor(nVehicleItemId) then
            return false, "invalid vehicle item ID"
        end
        VEHICLE_SLOTS[nSlotIndex] = nVehicleItemId
        return EquipVehicleToSlot(nVehicleItemId, nSlotIndex)
    end

    _G.SwapSocialLobbyVehicleSlots = SwapSocialLobbyVehicleSlots
    _G.SetSocialLobbyVehicleSlotId = SetSocialLobbyVehicleSlotId

    function EquipAllFromLists()
        local uid = DataMgr and DataMgr.roleData and tonumber(DataMgr.roleData.uid)
        if not uid then return 0 end
        local tSocialData = orig_GetSocialData(Logic_SocialLobbyModule, uid)
        if not tSocialData then return 0 end
        WriteAllSlotsTo(tSocialData)
        return 1
    end

    -- ============================================================
    -- GetSocialData hook — the critical fix.
    -- Every read for self-user ensures our fake data is present.
    -- No recursion: uses WriteAllSlotsTo which doesn't call GetSocialData.
    -- ============================================================
    Logic_SocialLobbyModule.GetSocialData = function(self, uid)
        local data = orig_GetSocialData(self, uid)
        if data and isSelfUid(uid) then
            pcall(function() WriteAllSlotsTo(data) end)
            pcall(FireShowDataEvent)
        end
        return data
    end

    -- ============================================================
    -- Lock/unlock getters
    -- ============================================================
    local orig_GetSlotTypeMaxCount = Logic_SocialLobbyModule.GetSlotTypeMaxCount
    Logic_SocialLobbyModule.GetSlotTypeMaxCount = function(self, nUId, nSlotType, bIsGetShowCount)
        if isSelfUid(nUId) then
            if nSlotType == SLOT_WEAPON then return WEAPON_SLOTS_MAX end
            if nSlotType == SLOT_VEHICLE then return VEHICLE_SLOTS_MAX end
            if nSlotType == SLOT_AVATAR then return AVATAR_SLOTS_MAX end
            if nSlotType == SLOT_PET then return PET_SLOTS_MAX end
        end
        return orig_GetSlotTypeMaxCount(self, nUId, nSlotType, bIsGetShowCount)
    end

    local orig_GetSlotIsUnlock = Logic_SocialLobbyModule.GetSlotIsUnlockBySlotTypeAndIndex
    Logic_SocialLobbyModule.GetSlotIsUnlockBySlotTypeAndIndex = function(self, nUId, nSlotType, nSlotIndex)
        if nSlotType ~= SLOT_BGWALL and isSelfUid(nUId) then return true end
        return orig_GetSlotIsUnlock(self, nUId, nSlotType, nSlotIndex)
    end

    local orig_GetSlotIsUnlockedByLevel = Logic_SocialLobbyModule.GetSlotIsUnlockedByCollectHallLevel
    Logic_SocialLobbyModule.GetSlotIsUnlockedByCollectHallLevel = function(self, nUId, nSlotType, nSlotIndex)
        if nSlotType ~= SLOT_BGWALL and isSelfUid(nUId) then return true end
        return orig_GetSlotIsUnlockedByLevel(self, nUId, nSlotType, nSlotIndex)
    end

    local orig_GetUCUnlockMax = Logic_SocialLobbyModule.GetSlotTypeUCUnlockMaxCount
    Logic_SocialLobbyModule.GetSlotTypeUCUnlockMaxCount = function(self, nSlotType)
        if nSlotType == SLOT_WEAPON then return WEAPON_SLOTS_MAX end
        if nSlotType == SLOT_VEHICLE then return VEHICLE_SLOTS_MAX end
        if nSlotType == SLOT_AVATAR then return AVATAR_SLOTS_MAX end
        if nSlotType == SLOT_PET then return PET_SLOTS_MAX end
        return orig_GetUCUnlockMax(self, nSlotType)
    end

    local orig_GetAllUnlockData = Logic_SocialLobbyModule.GetSlotTypeAllUnlockData
    Logic_SocialLobbyModule.GetSlotTypeAllUnlockData = function(self, nUId, nSlotType)
        if nSlotType ~= SLOT_BGWALL and isSelfUid(nUId) then
            ForceUnlockAllSlots()
            local tSocialData = orig_GetSocialData(self, nUId)
            return tSocialData and tSocialData.mixed_hall_slot_unlock_info
                and tSocialData.mixed_hall_slot_unlock_info[nSlotType] or {}
        end
        return orig_GetAllUnlockData(self, nUId, nSlotType)
    end

    local orig_CheckUCUnlock = Logic_SocialLobbyModule.CheckSlotTypeIsUCUnlock
    Logic_SocialLobbyModule.CheckSlotTypeIsUCUnlock = function(self, nSlotType, nSlotIndex)
        if nSlotType == SLOT_WEAPON or nSlotType == SLOT_VEHICLE
            or nSlotType == SLOT_AVATAR or nSlotType == SLOT_PET then
            return false
        end
        return orig_CheckUCUnlock(self, nSlotType, nSlotIndex)
    end

    local orig_GetUnlockCountByLevel = Logic_SocialLobbyModule.GetSlotUnlockCountByCollectHallLevel
    Logic_SocialLobbyModule.GetSlotUnlockCountByCollectHallLevel = function(self, nUId, nSlotType)
        if isSelfUid(nUId) then
            if nSlotType == SLOT_WEAPON then return WEAPON_SLOTS_MAX end
            if nSlotType == SLOT_VEHICLE then return VEHICLE_SLOTS_MAX end
            if nSlotType == SLOT_AVATAR then return AVATAR_SLOTS_MAX end
            if nSlotType == SLOT_PET then return PET_SLOTS_MAX end
        end
        return orig_GetUnlockCountByLevel(self, nUId, nSlotType)
    end

    local orig_GetWeaponSlotShow = Logic_SocialLobbyModule.GetWeaponSlotIsShowBySlotIndex
    Logic_SocialLobbyModule.GetWeaponSlotIsShowBySlotIndex = function(self, nSlotIndex)
        if isSelfUid(self._sCurUId) then return true end
        return orig_GetWeaponSlotShow(self, nSlotIndex)
    end

    Logic_SocialLobbyModule._tWeaponSlotIndex = { [1] = {}, [2] = {} }
    for page = 1, 2 do
        for i = 1, WEAPON_SLOTS_MAX do
            Logic_SocialLobbyModule._tWeaponSlotIndex[page][i] = true
        end
    end

    -- ============================================================
    -- Slot 3D UI hooks
