    -- ============================================================
    -- FAKE SAVE DISPLAY PATCH
    -- ============================================================
    local function ReapplyAndRefresh()
        pcall(ForceUnlockAllSlots)
        pcall(EquipAllFromLists)
        pcall(FireShowDataEvent)
    end

    local function ForceExitEditMode(EditMgr)
        if not EditMgr then return end
        local exitNames = {
            "ExitEditState", "LeaveEditState", "ExitEdit",
            "CancelEdit", "CloseEditState", "CloseEdit",
            "OnExitEditState", "QuitEdit", "FinishEdit", "EndEdit"
        }
        for _, name in ipairs(exitNames) do
            pcall(function()
                if type(EditMgr[name]) == "function" then EditMgr[name](EditMgr) end
            end)
        end
    end

    local function ExtractItemFromArgs(...)
        local itemId, slotIdx, slotType
        for _, a in ipairs({ ... }) do
            if type(a) == "number" then
                if not slotType and (a == 1 or a == 2 or a == 3 or a == 4) then
                    slotType = a
                elseif not itemId then
                    itemId = a
                elseif not slotIdx then
                    slotIdx = a
                end
            elseif type(a) == "table" then
                slotType = slotType or a.slot_type or a.slotType or a.nSlotType or a.type
                itemId   = itemId   or a.resid or a.item_id or a.itemId or a.id or a.pet_id or a.nItemId
                slotIdx  = slotIdx  or a.slot_index or a.slotIndex or a.slot or a.index or a.nSlotIndex
            end
        end
        return itemId, slotIdx, slotType
    end

    local function EquipBySlotType(slotType, itemId, slotIdx)
        slotIdx = tonumber(slotIdx) or 1
        if slotType == SLOT_VEHICLE then return EquipVehicleToSlot(itemId, slotIdx) end
        if slotType == SLOT_WEAPON  then return EquipWeaponToSlot(itemId, slotIdx) end
        if slotType == SLOT_AVATAR  then return EquipAvatarToSlot(itemId, slotIdx) end
        if slotType == SLOT_PET     then return EquipPetToSlot(itemId, slotIdx) end
        return false
    end

    local function SlotTableFor(slotType)
        if slotType == SLOT_VEHICLE then return VEHICLE_SLOTS end
        if slotType == SLOT_WEAPON  then return WEAPON_SLOTS end
        if slotType == SLOT_AVATAR  then return AVATAR_SLOTS end
        if slotType == SLOT_PET     then return PET_SLOTS end
        return nil
    end

    pcall(function()
        local EditMgr = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.Logic_SocialLobbyEditMgrModule)
        if not EditMgr then return end
        local blockKws = {
            "ReqSave", "ReqConfirm", "ReqApply", "ReqSubmit", "ReqSet", "ReqUpdate",
            "ReqCommit", "ReqSend", "ReqModify",
            "SaveEdit", "SaveShow", "SaveDisplay", "SaveSlot", "SaveMixed",
            "ConfirmEdit", "ConfirmShow", "ConfirmDisplay", "ConfirmSlot", "ConfirmMixed",
            "ApplyEdit", "ApplyShow", "ApplyDisplay", "ApplySlot", "ApplyMixed",
            "SubmitEdit", "SubmitShow", "SubmitDisplay", "SubmitSlot", "SubmitMixed",
        }
        for k, v in pairs(EditMgr) do
            if type(v) == "function" and type(k) == "string" then
                for _, kw in ipairs(blockKws) do
                    if k:find(kw, 1, true) then
                        EditMgr[k] = function(self, ...)
                            ReapplyAndRefresh()
                            ForceExitEditMode(EditMgr)
                            ReapplyAndRefresh()
                            return true
                        end
                        break
                    end
                end
            end
        end
    end)

    pcall(function()
        local EditMgr = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.Logic_SocialLobbyEditMgrModule)
        if not EditMgr then return end
        local function classifyByKeyword(name)
            local l = name:lower()
            if l:find("vehicle") or l:find("car") then return SLOT_VEHICLE end
            if l:find("weapon") or l:find("gun") then return SLOT_WEAPON end
            if l:find("avatar") or l:find("outfit") or l:find("cloth") then return SLOT_AVATAR end
            if l:find("pet") then return SLOT_PET end
            return nil
        end
        for k, v in pairs(EditMgr) do
            if type(v) == "function" and type(k) == "string" then
                local hasVerb = k:find("Select", 1, true) or k:find("Choose", 1, true) or k:find("Pick", 1, true)
                if hasVerb then
                    local kwSlotType = classifyByKeyword(k)
                    if not EditMgr["_fake_sel_" .. k] then
                        EditMgr["_fake_sel_" .. k] = true
                        EditMgr[k] = function(self, ...)
                            local itemId, slotIdx, argSlotType = ExtractItemFromArgs(...)
                            local finalSlotType = kwSlotType or argSlotType
                            if itemId and itemId > 0 and finalSlotType then
                                slotIdx = slotIdx or 1
                                local tbl = SlotTableFor(finalSlotType)
                                if tbl then tbl[slotIdx] = itemId end
                                pcall(EquipBySlotType, finalSlotType, itemId, slotIdx)
                            end
                            local ok, res = pcall(v, self, ...)
                            ReapplyAndRefresh()
                            return ok and res or nil
                        end
                    end
                end
            end
        end
    end)

    pcall(function()
        local EditMgr = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.Logic_SocialLobbyEditMgrModule)
        if not EditMgr then return end
        local enterNames = { "EnterEditState", "EnterEdit", "BeginEdit", "StartEdit", "OpenEditState" }
        for _, name in ipairs(enterNames) do
            if type(EditMgr[name]) == "function" and not EditMgr["_fake_enter_" .. name] then
                EditMgr["_fake_enter_" .. name] = true
                local orig = EditMgr[name]
                EditMgr[name] = function(self, ...)
                    local res = orig(self, ...)
                    ReapplyAndRefresh()
                    return res
                end
            end
        end
    end)

    -- Block network sends for slot/show data (Logic module)
    pcall(function()
        local blockKws = {
            "ReqSetMixed", "ReqSaveMixed", "ReqSetShow", "ReqSaveShow",
            "ReqSetSocialLobby", "ReqSetSlot", "ReqSaveSlot", "ReqSetDisplay",
            "SendSlot", "SendMixed", "SendShow", "SendSocial", "SendDisplay",
        }
        for k, v in pairs(Logic_SocialLobbyModule) do
            if type(v) == "function" and type(k) == "string" then
                for _, kw in ipairs(blockKws) do
                    if k:find(kw, 1, true) then
                        Logic_SocialLobbyModule[k] = function(self, ...)
                            ReapplyAndRefresh()
                            return true
                        end
                        break
                    end
                end
            end
        end
    end)

    -- ============================================================
    -- Network receive hooks — reapply after server pushes
    -- ============================================================
    pcall(function()
        local recvKws = { "OnRecv", "OnSync", "OnPush", "OnUpdate", "OnSocialLobbyShow", "OnSocialLobbyData" }
        for k, v in pairs(Logic_SocialLobbyModule) do
            if type(v) == "function" and type(k) == "string" then
                for _, p in ipairs(recvKws) do
                    if k:find(p, 1, true) then
                        if not Logic_SocialLobbyModule["_fake_recv_" .. k] then
                            Logic_SocialLobbyModule["_fake_recv_" .. k] = true
                            local orig = v
                            Logic_SocialLobbyModule[k] = function(self, ...)
                                local ok, res = pcall(orig, self, ...)
                                pcall(ForceUnlockAllSlots)
                                pcall(EquipAllFromLists)
                                pcall(FireShowDataEvent)
                                return ok and res or nil
                            end
                        end
                        break
                    end
                end
            end
        end
    end)

    -- ============================================================
    -- Global helpers
    -- ============================================================
    function SetSocialLobbyWeaponSlotId(nSlotIndex, nWeaponItemId)
        nSlotIndex = tonumber(nSlotIndex); nWeaponItemId = tonumber(nWeaponItemId)
        if not nSlotIndex or nSlotIndex < 1 or nSlotIndex > WEAPON_SLOTS_MAX then return false, "invalid slot" end
        if not nWeaponItemId or nWeaponItemId <= 0 then return false, "invalid id" end
        WEAPON_SLOTS[nSlotIndex] = nWeaponItemId
        return EquipWeaponToSlot(nWeaponItemId, nSlotIndex)
    end
    function SetSocialLobbyAvatarSlotId(nSlotIndex, nItemId)
        nSlotIndex = tonumber(nSlotIndex); nItemId = tonumber(nItemId)
        if not nSlotIndex or nSlotIndex < 1 or nSlotIndex > AVATAR_SLOTS_MAX then return false, "invalid slot" end
        if not nItemId or nItemId <= 0 then return false, "invalid id" end
        AVATAR_SLOTS[nSlotIndex] = nItemId
        return EquipAvatarToSlot(nItemId, nSlotIndex)
    end
    function SetSocialLobbyPetSlotId(nSlotIndex, nPetId)
        nSlotIndex = tonumber(nSlotIndex); nPetId = tonumber(nPetId)
        if not nSlotIndex or nSlotIndex < 1 or nSlotIndex > PET_SLOTS_MAX then return false, "invalid slot" end
        if not nPetId or nPetId <= 0 then return false, "invalid id" end
        PET_SLOTS[nSlotIndex] = nPetId
        return EquipPetToSlot(nPetId, nSlotIndex)
    end
    function ReloadSocialLobbyDisplay()
        ReapplyAndRefresh()
        pcall(FireAllSlotEvents)
        return true
    end

    _G.SetSocialLobbyWeaponSlotId = SetSocialLobbyWeaponSlotId
    _G.SetSocialLobbyAvatarSlotId = SetSocialLobbyAvatarSlotId
    _G.SetSocialLobbyPetSlotId    = SetSocialLobbyPetSlotId
    _G.ReloadSocialLobbyDisplay   = ReloadSocialLobbyDisplay
    _G.ReapplySocialLobbyDisplay  = ReapplyAndRefresh

    _G.SocialLobbyVehicleSlots = VEHICLE_SLOTS
    _G.SocialLobbyWeaponSlots  = WEAPON_SLOTS
    _G.SocialLobbyAvatarSlots  = AVATAR_SLOTS
    _G.SocialLobbyPetSlots     = PET_SLOTS

    -- ============================================================
    -- INITIAL APPLY + CONTINUOUS REAPPLY LOOP
    -- ============================================================
    pcall(function()
        ForceUnlockAllSlots()
        EquipAllFromLists()
        FireShowDataEvent()
    end)

    pcall(function()
        local tt = require("common.time_ticker")
        if not tt then return end
        -- Staggered initial fires handle race with server show-data
        for _, d in ipairs({ 0.1, 0.3, 0.6, 1.0, 1.5, 2.5, 4.0, 6.0 }) do
            if tt.AddTimerOnce then
                tt.AddTimerOnce(d, function()
                    pcall(ReapplyAndRefresh)
                    pcall(FireAllSlotEvents)
                end)
            end
        end
        -- Continuous reapply loop — catches every server overwrite
        if tt.AddTimerOnce then
            local function tick()
                pcall(ForceUnlockAllSlots)
                pcall(EquipAllFromLists)
                pcall(FireShowDataEvent)
                tt.AddTimerOnce(1.0, tick)
            end
            tt.AddTimerOnce(1.5, tick)
        end
    end)
end)
