local CACHE_COUNTER_BOT_BG      = g_Botmater_ESPColor(1.0, 1.0, 1.0, 1.0)     -- Nền BOT: Trắng đặc 100% (Giữ nguyên)
local CACHE_COUNTER_PLAYER_TEXT = g_Botmater_ESPColor(0.0, 0.0, 0.0, 1.0)     -- Chữ REAL: Đen
