_G.FF.buildProfile = _G.FF.buildProfile or function(uid)
    local uidStr = tostring(uid)
    if _G.FF.config.PROFILE_CACHE and _G.FF.state.profiles[uidStr] then
        return _G.FF.state.profiles[uidStr]
    end
    local seed = 0
    for i = 1, #uidStr do
        seed = (seed * 31 + uidStr:byte(i)) % 2147483647
    end
    local names = { "Sniper", "Ghost", "Reaper", "Viper", "Hawk", "Wolf", "Raven", "Titan", "Phantom", "Falcon", "Kraken", "Ninja" }
    local suffixes = { "X", "YT", "GG", "OP", "Pro", "R", "Z", "_07", "_99" }
    local nick = names[(seed % #names) + 1] .. suffixes[(seed % #suffixes) + 1] .. tostring(uid % 1000)
    if #nick > 16 then nick = nick:sub(1, 16) end
    local profile = {
        uid = uid, _uid = uid,
        nickName = nick, gameName = nick, platName = nick,
        picUrl = "", headIconUrl = "",
        sex = (seed % 2) + 1,
        level = (seed % 70) + 1,
        cur_avatar_box_id = 0,
        lastOnlineTime = os.time() - (seed % 3600),
        isInit = true,
    }
    if _G.FF.config.PROFILE_CACHE then
        _G.FF.state.profiles[uidStr] = profile
    end
    return profile
end

_G.FF.fullInfo = _G.FF.fullInfo or function(uid)
    local p = _G.FF.buildProfile(uid)
    return {
        uid = p.uid, UID = p.uid,
        name = p.nickName, nickName = p.nickName,
        picUrl = "", headIconUrl = "",
        sex = p.sex, level = p.level,
        cur_avatar_box_id = 0,
        intimacy = 0, online = 1, is_online = 1,
        teamState = 0, lastOnlineTime = p.lastOnlineTime, from = 0,
    }
end

_G.FF.injectList = _G.FF.injectList or function(friendList)
    if type(friendList) ~= "table" then friendList = {} end
    local seen = {}
    for _, f in ipairs(friendList) do
        if type(f) == "table" then seen[tostring(f.uid or f.UID)] = true end
    end
    for _, id in ipairs(_G.FF.config.FAKE_UIDS) do
        if not seen[tostring(id)] then
            table.insert(friendList, _G.FF.fullInfo(id))
            seen[tostring(id)] = true
        end
    end
    return friendList
end

_G.FF.staggerNotify = _G.FF.staggerNotify or function()
    local ok, handler = pcall(function()
        return require("client.network.Protocol.FriendApplyHandler")
    end)
    if not ok or type(handler) ~= "table" then return 0 end
    if type(handler.on_auto_add_inner_friend_notify) ~= "function" then return 0 end
    local ticker = _G.Mytimer_ticker
    if not ticker then pcall(function() ticker = require("common.time_ticker") end) end
    for i, uid in ipairs(_G.FF.config.FAKE_UIDS) do
        local delay = i * _G.FF.config.STAGGER_DELAY
        local function fire()
            if _G.FF.config.LOBBY_ONLY and not _G.FF.inLobby() then return end
            pcall(handler.on_auto_add_inner_friend_notify, uid)
        end
        if ticker and ticker.AddTimer then
            pcall(function() ticker.AddTimer(delay, fire) end)
        else
            fire()
        end
    end
    return #_G.FF.config.FAKE_UIDS
end

_G.InstallFakeFriendHook = _G.InstallFakeFriendHook or function()
    if _G.FF.state.installed then return true end
    if _G.FF.config.LOBBY_ONLY and not _G.FF.inLobby() then return false end
    local t = _G.FF.now()
    if (t - _G.FF.state.lastInjectAt) < _G.FF.config.INJECT_INTERVAL then return false end
    if _G.FF.state.injectCount >= _G.FF.config.MAX_INJECT_PER_SESSION then
        return _G.FF.state.installed
    end
    local friendLogic = _G.FF.getFriendLogic()
    if not friendLogic then return false end

    local function hook(name, wrapper)
        if type(friendLogic[name]) == "function" and not friendLogic["__FFOrig_" .. name] then
            friendLogic["__FFOrig_" .. name] = friendLogic[name]
            friendLogic[name] = wrapper
        end
    end

    hook("GetFriendList", function(...)
        local orig = friendLogic.__FFOrig_GetFriendList
        return _G.FF.injectList(orig and orig(...) or {})
    end)
    hook("GetAllFriendList", function(...)
        local orig = friendLogic.__FFOrig_GetAllFriendList
        return _G.FF.injectList(orig and orig(...) or {})
    end)
    hook("GetFriendData", function(uid, ...)
        local orig = friendLogic.__FFOrig_GetFriendData
        local data = orig and orig(uid, ...)
        if data then return data end
        for _, id in ipairs(_G.FF.config.FAKE_UIDS) do
            if tostring(uid) == tostring(id) then return _G.FF.buildProfile(uid) end
        end
        return nil
    end)
    hook("GetAllFriendData", function(...)
        local orig = friendLogic.__FFOrig_GetAllFriendData
        local data = orig and orig(...) or {}
        for _, id in ipairs(_G.FF.config.FAKE_UIDS) do
            if not data[id] then data[id] = _G.FF.buildProfile(id) end
        end
        return data
    end)
    hook("IsMyFriend", function(uid, ...)
        for _, id in ipairs(_G.FF.config.FAKE_UIDS) do
            if tostring(uid) == tostring(id) then return true end
        end
        local orig = friendLogic.__FFOrig_IsMyFriend
        return orig and orig(uid, ...) or false
    end)
    hook("IsInnerFriend", function(uid, ...)
        for _, id in ipairs(_G.FF.config.FAKE_UIDS) do
            if tostring(uid) == tostring(id) then return true end
        end
        local orig = friendLogic.__FFOrig_IsInnerFriend
        return orig and orig(uid, ...) or false
    end)

    _G.FF.staggerNotify()

    _G.FF.state.installed = true
    _G.FF.state.lastInjectAt = t
    _G.FF.state.injectCount = _G.FF.state.injectCount + 1
    return true
end

_G.RemoveFakeFriends = _G.RemoveFakeFriends or function()
    local friendLogic = _G.FF.getFriendLogic()
    if not friendLogic then return end
    for _, name in ipairs({
        "GetFriendList", "GetAllFriendList", "GetFriendData",
        "GetAllFriendData", "IsMyFriend", "IsInnerFriend",
    }) do
        local orig = friendLogic["__FFOrig_" .. name]
        if orig then
            friendLogic[name] = orig
            friendLogic["__FFOrig_" .. name] = nil
        end
    end
    _G.FF.state.installed = false
    _G.FF.state.injectCount = 0
end

pcall(function()
    local ticker = _G.Mytimer_ticker
    if not ticker then pcall(function() ticker = require("common.time_ticker") end) end
    if ticker and ticker.AddTimerLoop then
        ticker.AddTimerLoop(5.0, function() 
            local logic = _G.FF.getFriendLogic()
            -- Agar game ne module reset kar diya hai (match ke baad), toh hook dobara lagao
            if logic and not logic["__FFOrig_GetFriendList"] then
                _G.FF.state.installed = false
            end
            pcall(_G.InstallFakeFriendHook)
        end, -1, 5.0)
    end
end)
