-- ================= CUSTOM KILL COUNTER FROM TXT (UXOfficial) ======================
-- ==============================================================================
do
    _G.UXOfficial_KILLS = _G.UXOfficial_KILLS or {
        TotalKills = 50,
        Headshots = 10,
        WeaponKills = { ["M416"] = 15, ["AKM"] = 10 }
    }

    local function GetKillPaths()
        local fileName = "UXOfficial_KILLS.txt"
        local paths = {
            -- ================= ANDROID PATHS =================
            "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            
            -- ================= IOS / IPAD STANDARD PATHS =================
            "Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "../Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "../../Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "../../ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "../Library/Caches/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            
            -- ================= IOS JAILBREAK / SYSTEM PATHS =================
            "/var/mobile/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "/private/var/mobile/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,

            -- ================= FALLBACK =================
            fileName
        }

        -- [IOS/IPAD DYNAMIC SANDBOX DETECTION]
        -- Ye line iPhone/iPad ka asli app folder (var/mobile/Containers...) auto-dhundh legi
        pcall(function()
            if os and os.getenv then
                local homeDir = os.getenv("HOME")
                if homeDir and homeDir ~= "" then
                    table.insert(paths, 1, homeDir .. "/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
                    table.insert(paths, 2, homeDir .. "/Library/Caches/ShadowTrackerExtra/Saved/Paks/" .. fileName)
                end
            end
        end)

        return paths
    end

    local function LoadKillsFromTxt()
        local paths = GetKillPaths()
        for _, path in ipairs(paths) do
            local file = io.open(path, "r")
            if file then
                local content = file:read("*a")
                file:close()
                
                -- Parse the text file (supports Lua table format)
                local func = load(content)
                if func then
                    local ok, data = pcall(func)
                    if ok and type(data) == "table" then
                        _G.UXOfficial_KILLS = data
                        return true
                    end
                else
                    -- Agar user ne seedha number likha hai (e.g. "99")
                    local num = tonumber(content)
                    if num then
                        _G.UXOfficial_KILLS.TotalKills = num
                        return true
                    end
                end
            end
        end
        return false
    end

    local function SaveKillsToTxt()
        local data = "return {\n"
        data = data .. "    TotalKills = " .. tostring(_G.UXOfficial_KILLS.TotalKills or 0) .. ",\n"
        data = data .. "    Headshots = " .. tostring(_G.UXOfficial_KILLS.Headshots or 0) .. ",\n"
        data = data .. "    WeaponKills = {\n"
        for w, c in pairs(_G.UXOfficial_KILLS.WeaponKills or {}) do
            data = data .. "        [\"" .. tostring(w) .. "\"] = " .. tostring(c) .. ",\n"
        end
        data = data .. "    }\n}"
        
        local paths = GetKillPaths()
        for _, path in ipairs(paths) do
            local file = io.open(path, "w")
            if file then
                file:write(data)
                file:close()
                break -- Ek path pe save ho gaya toh ruk jao
            end
        end
    end

    -- Auto Create & Load on Start
    local loaded = LoadKillsFromTxt()
    if not loaded then
        SaveKillsToTxt() -- Agar file nahi mili toh default bana do
    end

    -- Loop to update from txt every 3 seconds
    pcall(function()
        local ticker = _G.Mytimer_ticker or require("common.time_ticker")
        if ticker and ticker.AddTimerLoop then
            ticker.AddTimerLoop(3.0, function()
                pcall(LoadKillsFromTxt)
            end, -1, 3.0)
        end
    end)
end
