                    DataMgr.roleData.brief_collect_data = {}
                end
                local b = DataMgr.roleData.brief_collect_data
                b.level = FAKE_LEVEL
                b.dan = FAKE_DAN
                b.total_score = FAKE_SCORE
                b.perk_light = true
                b.is_light_up = true
                b.perk_open = true
                b.active_perk_id = PERK_ID
                b.perk_id = PERK_ID
            end
        end)
    end

    -- ========== UI REFRESH ==========
    local function refresh_ui(mod)
        pcall(function()
            if mod and mod.RefreshView then mod:RefreshView() end
        end)
        pcall(function()
            if mod and mod.OnRefreshView then mod:OnRefreshView() end
        end)
        pcall(function()
            if mod and mod.RefreshMainView then mod:RefreshMainView() end
        end)
        -- Force event dispatch
        pcall(function()
            if _G.EventDispatcher and _G.EventConst then
                local ev = _G.EventConst
                local disp = _G.EventDispatcher
                if ev.ROLE_INFO_REFRESH then disp:DispatchEvent(ev.ROLE_INFO_REFRESH) end
                if ev.COLLECT_DATA_REFRESH then disp:DispatchEvent(ev.COLLECT_DATA_REFRESH) end
            end
        end)
    end

    -- ========== APPLY ==========
    local function apply_collection()
        hook_collect_handler()
        local cm = get_collect_module()
        if cm then patch_collect_module(cm) end
        for _, mod in pairs(package.loaded or {}) do
            if type(mod) == "table" and mod.GetLevelDataByScore and mod.GetSeasonLevelByScore then
                patch_collect_module(mod)
            end
        end
        inject_role_data()
        refresh_ui(cm)
    end

    apply_collection()

    pcall(function()
        local ticker = require("common.time_ticker")
        if ticker and ticker.AddTimerLoop then
            ticker.AddTimerLoop(REAPPLY_SEC, apply_collection, -1, 0)
        end
    end)

    print(string.format("[BeysaCollection] Level=%d Dan=%d Score=%d PerkID=%s", FAKE_LEVEL, FAKE_DAN, FAKE_SCORE, tostring(PERK_ID)))
end)

