-- ============================================================
-- BeyzaStudios — v20.7 (global rewrite, 0 local slots)
-- Fixes: "too many local variables (limit is 200) in main function"
-- ============================================================
-- ============================================================
-- ISIM DEGISTIR + KAYDET POPUP (V21.0) - iPad & Android Fixed
-- 1) ASAGIDAKI BLOK: dosyada "ISIM (BeysaName.ini)" bolumunden
--    "===== V21.0 SONU =====" satirina kadar olan kismin yerine gecer.
--    Ayni bolumde FILES, post, F, GetCanvas, LegalMsg, GameplayData, UEnums
--    onceden tanimli olmali.
-- 2) MENU PARCALARI (2a, 2b) en altta.
-- Owner PatronPubgBeysa & Creator Neysa
-- ============================================================
-- ============================================================
-- ISIM DEGISTIR + KAYDET POPUP (V20.9c)
-- Single do-block: 0 outer locals, N.run = universal pcall helper
-- iPad/iOS + Android writable path auto-detect
-- Toggle ON -> top big box, Enter -> save + force apply
-- Session keep-alive, unlimited tries, client-side fake visual
-- Owner PatronPubgBeysa & Creator Neysa
-- ============================================================
--BeyzaStudios
--BeyzaStudios
_G.BeysaName = _G.BeysaName or {}
-- IIFE START: main chunk ki 200 local limit bypass karne ke liye
(function()
    local N = _G.BeysaName
    N.name = N.name or ""

    -- ========================================================
    -- UNIVERSAL PCALL HELPER
    -- ========================================================
    N.run = function(fn, ...)
        if type(fn) ~= "function" then return nil end
        local ok, r = pcall(fn, ...)
        if not ok then return nil end
        return r
    end

    N.log = function(msg)
        N.run(function()
            local f = io.open((FILES or "") .. "BeysaName.log", "a")
            if f then
                f:write(os.date("%H:%M:%S") .. " " .. tostring(msg) .. "\n")
                f:flush() f:close()
            end
        end)
    end
    N.plog = function(msg) N.run(N.log, "[popup] " .. tostring(msg)) end

    -- ========================================================
    -- PATH RESOLVE (iPad/iOS + Android)
    -- ========================================================
    do
        local base = FILES or ""
        local home = (os.getenv and os.getenv("HOME")) or "/var/mobile"
        local cands = {
            (base ~= "" and (base .. "BeysaName.ini")) or nil,
            home .. "/Documents/BeysaName.ini",
            "/var/mobile/Documents/BeysaName.ini",
            "/var/mobile/Containers/Data/Application/BeysaName.ini",
            "/var/mobile/Library/BeysaName.ini",
        }
        local picked
        for i = 1, #cands do
            local p = cands[i]
            if p and p ~= "" then
                local f = io.open(p, "a")
                if f then f:close() picked = p break end
            end
        end
        N.iniPath = picked or cands[1] or "/var/mobile/Documents/BeysaName.ini"
    end
    _G.BeysaNameIniPath = N.iniPath

    -- ========================================================
    -- LOAD / SAVE
    -- ========================================================
    N.loadName = function()
        N.name = ""
        local path = N.iniPath
        if not path then return end
        local f = io.open(path, "r")
        if not f then return end
        local txt = f:read("*a") f:close()
        local v = txt:match("NAME%s*=%s*([^\r\n]*)") or ""
        v = v:gsub("^%s+", ""):gsub("%s+$", "")
        N.name = v
    end

    N.saveNameIni = function(v)
        N.run(function()
            local w = io.open(N.iniPath, "w")
            if w then w:write("[Name]\nNAME=" .. tostring(v or "") .. "\n") w:close() end
        end)
    end

    -- ========================================================
    -- OBJECT CREATOR + TIMER
    -- ========================================================
    N.newObj = function(path)
        local o
        N.run(function() o = CGame:NewObjectFromPath(path) end)
        if not o then return nil end
        if N.run(function() return slua.isValid(o) end) then return o end
        return nil
    end

    -- ========================================================
    -- PROPER HOOK (Fix real name overwrite, no RPC spam)
    -- ========================================================
    N.applyHook = function()
        N.run(function()
            local DM = _G.DataMgr
            if DM and type(DM.UpdateNickName) == "function" and not _G.BeysaNameHooked then
                _G.BeysaNameHooked = true
                local orig = DM.UpdateNickName
                DM.UpdateNickName = function(self, incomingName)
                    if N.name ~= "" then
                        -- Force RoleData locals to fake name
                        pcall(function()
                            if DM.roleData then
                                if DM.roleData.Name ~= nil then DM.roleData.Name = N.name end
                                if DM.roleData.roleName ~= nil then DM.roleData.roleName = N.name end
                                if DM.roleData.nickName ~= nil then DM.roleData.nickName = N.name end
                            end
                        end)
                        return orig(self, N.name)
                    end
                    return orig(self, incomingName)
                end
                N.plog("Hook: DM.UpdateNickName intercepted")
            end
        end)
    end

    N.apply = function()
        if N.name == "" then return false end
        N.run(function()
            local DM = _G.DataMgr
            if DM and DM.roleData then
                pcall(function() DM.roleData.Name = N.name end)
                pcall(function() DM.roleData.roleName = N.name end)
                pcall(function() DM.roleData.nickName = N.name end)
            end
        end)
        N.run(function()
            local pc = GameplayData.GetPlayerCharacter()
            if slua.isValid(pc) then
                pcall(function() pc.PlayerName = N.name end)
            end
        end)
        -- Update UI
        N.run(function() post("EVENTTYPE_WARDROBE", "EVENTID_WARDROBE_UPDATE_ITEM_LIST") end)
        N.run(function() post("EVENTTYPE_ROLEINFO", "EVENTID_ROLEINFO_UPDATE_ROLENAME") end)
        return true
    end

    N.forceApply = function()
        if N.name == "" then return false end
        N.applyHook()
        return N.run(N.apply)
    end

    -- ========================================================
    -- POPUP LOGIC (Text Box)
    -- ========================================================
    do
        local P = { box=nil, shown=false, X=0, Y=25, W=420, H=52 }
        N.P = P

        P.getText = function()
            local t = ""
            N.run(function()
                if P.box and slua.isValid(P.box) then
                    t = tostring(P.box:GetText())
                end
            end)
            t = t:gsub("[\r\n]", ""):gsub("^%s+", ""):gsub("%s+$", "")
            return t
        end

        P.attachCommit = function()
            if not P.box or not slua.isValid(P.box) then return end
            N.run(function()
                P.box.OnTextCommitted:Add(function(_a, _b)
                    N.run(P.doApply)
                end)
            end)
        end

        P.build = function()
            if P.box and slua.isValid(P.box) then return true end
            local box = N.newObj("/Script/UMG.EditableTextBox")
            if not box then return false end
            
            N.run(function() box:SetHintText("Isim yaz, Enter'a bas") end)
            N.run(function() box:SetForegroundColor(FLinearColor(1, 1, 1, 1)) end)
            
            local added = false
            N.run(function()
                local hud = require("game_frontend_hud")
                if hud and hud.AddToContainer and UIContainers and UIContainers.Top then
                    hud.AddToContainer(UIContainers.Top, box, 99999)
                    added = true
                end
            end)
            if not added then
                local canvas = GetCanvas()
                if canvas then N.run(function() canvas:AddChildToCanvas(box) added = true end) end
            end
            if not added then
                N.run(function()
                    if box.AddToViewport then box:AddToViewport(99999) added = true end
                end)
            end
            if not added then return false end
            
            N.run(function()
                local WLL = import("WidgetLayoutLibrary")
                local slot = WLL.SlotAsCanvasSlot(box)
                if slot then
                    slot:SetAnchors(FAnchors(0.5, 0.0, 0.5, 0.0))
                    slot:SetAlignment(FVector2D(0.5, 0.0))
                    slot:SetPosition(FVector2D(P.X, P.Y))
                    slot:SetSize(FVector2D(P.W, P.H))
                end
            end)
            
            P.box = box
            P.attachCommit()
            return true
        end

        P.doApply = function()
            local t = P.getText()
            if t == "" or #t > 40 then return false end
            N.name = t
            N.saveNameIni(t)
            N.run(N.forceApply)
            N.run(function() if ShowNotice then ShowNotice(49951) end end)
            N.plog("uygulandi: " .. t)
            
            -- Auto-off removed: Box screen pe visible rahega
            return true
        end

        N.togglePopup = function()
            if not P.box or not slua.isValid(P.box) then
                if not P.build() then return false end
            end
            P.shown = not P.shown
            
            N.run(function()
                if UEnums and UEnums.ESlateVisibility and P.box and slua.isValid(P.box) then
                    local E = UEnums.ESlateVisibility
                    if P.shown then
                        if N.name ~= "" then pcall(function() P.box:SetText(N.name) end) end
                        P.box:SetVisibility(E.Visible)
                        P.box:SetKeyboardFocus()
                    else
                        P.box:SetVisibility(E.Collapsed)
                    end
                end
            end)
            return true
        end
    end

    -- INIT
    N.run(N.loadName)
    if N.name ~= "" then N.run(N.forceApply) end
end)()
